using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private readonly ShoppingCart _cart;

    public ShoppingCartTests()
    {
        _cart = new ShoppingCart();
    }

    // ─── AddItem ────────────────────────────────────────────────────────

    [TestMethod]
    public void AddItem_SingleItem_AppearsInCart()
    {
        _cart.AddItem("SKU-001", 2, 9.99m);

        Assert.HasCount(1, _cart.Items);
        Assert.AreEqual((2, 9.99m), _cart.Items["SKU-001"]);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_CombinesQuantity()
    {
        _cart.AddItem("SKU-001", 1, 5.00m);
        _cart.AddItem("SKU-001", 3, 5.00m);

        Assert.AreEqual(4, _cart.Items["SKU-001"].Quantity);
    }

    [TestMethod]
    public void AddItem_MultipleSkus_AllTracked()
    {
        _cart.AddItem("A", 1, 10m);
        _cart.AddItem("B", 2, 20m);
        _cart.AddItem("C", 3, 30m);

        Assert.HasCount(3, _cart.Items);
    }

    [TestMethod]
    public void AddItem_NullSku_Throws()
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.AddItem(null!, 1, 1m));
    }

    [TestMethod]
    public void AddItem_ZeroQuantity_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => _cart.AddItem("SKU", 0, 1m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => _cart.AddItem("SKU", 1, -1m));
    }

    // ─── RemoveItem ─────────────────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _cart.AddItem("SKU-001", 1, 5m);

        _cart.RemoveItem("SKU-001");

        Assert.IsEmpty(_cart.Items);
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_Throws()
    {
        Assert.ThrowsExactly<InvalidOperationException>(() => _cart.RemoveItem("GHOST"));
    }

    [TestMethod]
    public void RemoveItem_NullSku_Throws()
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.RemoveItem(null!));
    }

    // ─── CalculateTotal ─────────────────────────────────────────────────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsCorrectTotal()
    {
        _cart.AddItem("SKU-001", 3, 10.00m);

        Assert.AreEqual(30.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_SumsAll()
    {
        _cart.AddItem("A", 2, 5.00m);   // 10
        _cart.AddItem("B", 1, 15.00m);  // 15

        Assert.AreEqual(25.00m, _cart.CalculateTotal());
    }

    // ─── ApplyCoupon ────────────────────────────────────────────────────

    [TestMethod]
    [DataRow("SAVE10", 90.00)]
    [DataRow("SAVE20", 80.00)]
    [DataRow("HALF", 50.00)]
    public void ApplyCoupon_ValidCode_ReducesTotal(string code, double expectedTotal)
    {
        _cart.AddItem("SKU-001", 1, 100.00m);

        _cart.ApplyCoupon(code);

        Assert.AreEqual((decimal)expectedTotal, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_CaseInsensitive_Works()
    {
        _cart.AddItem("SKU-001", 1, 100m);

        _cart.ApplyCoupon("save10");

        Assert.AreEqual(90m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_Throws()
    {
        var ex = Assert.ThrowsExactly<ArgumentException>(() => _cart.ApplyCoupon("BOGUS"));
        Assert.Contains("BOGUS", ex.Message);
    }

    [TestMethod]
    public void ApplyCoupon_NullCode_Throws()
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.ApplyCoupon(null!));
    }

    [TestMethod]
    public void ApplyCoupon_ReplacedByNewCoupon_UsesLatest()
    {
        _cart.AddItem("SKU-001", 1, 100m);
        _cart.ApplyCoupon("SAVE10");
        _cart.ApplyCoupon("SAVE20");

        Assert.AreEqual(80m, _cart.CalculateTotal());
    }
}

